INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10900, 'koKR', 'Znak Vash', '', '', '', '', '', '', '', '', 0),
(10901, 'koKR', 'Maczuga Kar\'desha', 'Przynieś mi sygnety żywiołów, których wymaga maczuga!$B$BZiemny sygnet ma Gruul Smokobójca. Znajdziesz go w jego leżu w Górach Klingi.$B$BDrugim sygnetem jest płonące serce stworzenia zwanego Pożeraczem Nocy. Ta mityczna bestia podobno przebywa w świętych salach proroka Medivha.$B$BPośpiesz się!$B', 'Skar\'this Heretyk w heroicznych Zagrodach Niewolników w Zbiorniku Żmijokolców chce, żebyś $gprzyniósł:przyniosła; mu Ziemny sygnet i Płonący sygnet.', '', 'Wróć do Skar\'thisa Heretyka na Cyplu w Górach Alterak.', '', '', '', '', 0),
(11115, 'koKR', 'Znak Vash (FLAG ONLY)', '', '', '', '', '', '', '', '', 0),
(11691, 'koKR', 'Przyzwanie Ahuna', 'Wraz z moimi szamanami zgromadziliśmy moc przed nadchodzącą bitwą z Władcą Mrozu. $N, ty będziesz pięścią Matki Ziemi.$B$BWeź ten totem magmy. Użyj go na lodowym kamieniu na północnym wschodzie. Ahun przesyła przez ten kamień swoją moc; mamy nadzieję, że totem mu w tym przeszkodzi i odetnie go od planów żywiołów.$B$BJeśli los będzie nam sprzyjał, to może zdołamy go pokonać.$B$BPrzygotuj się, $n. Jeśli Ahun stanie z nami do walki, jego furia będzie wielka.', 'Zanieś totem magmy Kręgu Ziemi do lodowego kamienia.', '', 'Wróć do lodowego kamienia na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(11696, 'koKR', 'Ahun jest tutaj!', '$n, twoja obecność to błogosławieństwo. Ahun kryje się w tych jaskiniach i zbiera siły do ataku. Wysłano przodem siły Kręgu Ziemi, ale same go nie pokonają.$B$BRozejrzyj się tu, $n. Odszukaj naszych szamanów z Kręgu Ziemi i porozmawiaj z ich przywódczynią, Lumą Matką Niebios. Być może z twoją pomocą zdołamy pokonać Ahuna, zanim będzie za późno.', 'Odszukaj Lumę Matkę Niebios w Zagrodach Niewolników.', '', '', '', '', '', '', 0),
(11955, 'koKR', 'Ahun, Władca Mrozu', 'Wierzę, że masz dość sił, by podjąć się ostatecznego zadania, które przed nami stoi.$b$bNie możemy dopuścić, by spisek Kultu Zmierzchu i nagijskich heretyków Neptulona się powiódł. Dla dobra Azeroth i wszelkiego życia w tym świecie musimy działać. Nasza droga jest jasna. Musisz udać się do Zagród Niewolników w głębi Zbiornika Żmijokolców i spotkać się tam z naszą szamanką. Ruszaj, i to szybko!', 'Udaj się do Zagród Niewolników w Zbiorniku Żmijokolców na Moczarach Zangarskich i porozmawiaj z Numą Siostrą Chmur.', '', '', '', '', '', '', 0),
(11972, 'koKR', 'Odłamki Ahuna', 'Te odłamki pulsują złowieszczo. Czy kryje się w nich ostatnia esencja Władcy Mrozu?', 'Zanieś lodowe odłamki Lumie Matce Niebios.', '', 'Wróć do Lumy Matki Niebios w instancji Lorda Ahuna podczas Letniego Przesilenia.', '', '', '', '', 0),
(11976, 'koKR', 'Lodowe odłamki', 'Te odłamki pulsują złowieszczo. Czy kryje się w nich ostatnia esencja Władcy Mrozu?', 'Zanieś lodowe odłamki Lumie Matce Niebios.', '', 'Wróć do Lumy Matki Niebios na Wzgórzu Darrow w Międzygórzu.', '', '', '', '', 0),
(13431, 'koKR', 'Maczuga Kar\'desha', 'Przynieś mi sygnety żywiołów, których wymaga maczuga!$B$BZiemny sygnet ma Gruul Smokobójca. Znajdziesz go w jego leżu w Górach Klingi.$B$BDrugim sygnetem jest płonące serce stworzenia zwanego Pożeraczem Nocy. Ta mityczna bestia podobno przebywa w świętych salach proroka Medivha.$B$BPośpiesz się!$B', 'Skar\'this Heretyk w heroicznych Zagrodach Niewolników w Zbiorniku Żmijokolców chce, żebyś $gprzyniósł:przyniosła; mu Ziemny sygnet i Płonący sygnet.', '', 'Wróć do Skar\'thisa Heretyka na Cyplu w Górach Alterak.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(10900, 'koKR', 'Spal to! Spal to wszystko doszczętnie! Na nic nie zasługują! Słyszysz?! NA NIC! Muszą zapłacić za to, co zrobili. I za to, co wciąż robią.$B$BSam zabiłbym Vash, gdybym tylko zdołał zerwać te przeklęte więzy.$B$BA może chcesz wykonać dzieło Neptulona? Jej śmierć posłuży nam obu, $gmiękkoskóry:miękkoskóra;. Pomożesz mi odtworzyć świętą maczugę?', 0),
(10901, 'koKR', 'Nareszcie!$B$BNie zapomniałem o naszej umowie, $gśmiertelniku:śmiertelniczko;. Ty też możesz teraz wejść do leża Lady Vash. A teraz zostaw mnie! Mam wiele do zaplanowania.', 0),
(11691, 'koKR', 'Gdy totem magmy zbliża się do lodowego kamienia, rozpada się na trzy osobne płomienie. Kamień migocze, po czym znika...', 0),
(11696, 'koKR', 'Chłód Ahuna rozchodzi się po tych jaskiniach, $N; to zalążek lodowatej śmierci, która nas czeka, jeśli odzyska on pełnię sił. Dziękuję Matce Ziemi, że cię przysłała.', 0),
(11955, 'koKR', 'Dzięki duchom, że jesteś! Musimy szybko przyzwać Ahuna, zanim będzie za późno...', 0),
(11972, 'koKR', 'Tak, w tych odłamkach kryje się ostatnia esencja Władcy Mrozu w tej krainie. Pozbędziemy się ich i wygnamy Ahuna w otchłanne krainy chłodu.$B$BDziękuję ci, $N. Twoje imię będzie rozbrzmiewać w pieśniach Kręgu Ziemi po kres dni. Uczyń nam ten zaszczyt i przyjmij tę pamiątkę – symbol twojego pokrewieństwa z ciepłem i światłem.', 0),
(13431, 'koKR', 'Nareszcie!$b$bGdy te więzy są zerwane, a maczuga w moim ręku, odeślę tę morską wiedźmę z powrotem w lodowate głębiny...', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(10901, 'koKR', 'Gdy maczuga zostanie odtworzona, zerwę więzy i wrócę do Wężowej Głębiny, by zemścić się na Vash i jej sługach!', 0),
(11691, 'koKR', 'Ten odłamek lodu niesie echo głębokiego, trzeszczącego dudnienia nacierających lodowców. Bijący od niego chłód kieruje twoje myśli ku martwej, niekończącej się zimie.', 0),
(11972, 'koKR', 'Witaj, $N. Wyglądasz na $gzmartwionego:zmartwioną;, a przecież trzeba się radować. Władca Mrozu został pokonany!', 0),
(13431, 'koKR', 'Gdy maczuga zostanie odtworzona, zerwę więzy i wrócę do Wężowej Głębiny, by zemścić się na Vash i jej sługach!', 0);
