INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(14405, 'koKR', 'Pobudka! Wstawaj i wracaj do roboty!', '', 0),
(14412, 'koKR', 'Pośpiesz się wreszcie! Im dłużej się guzdrzesz, tym bardziej oberwiesz!', '', 0),
(14413, 'koKR', 'Co to ma być?! Mamusia i tatuś niczego cię nie nauczyli?!', '', 0),
(14414, 'koKR', 'Okropność... ręce mi już mdleją od bicia was, leniwe robaki!', '', 0),
(14415, 'koKR', 'Za wcześnie! Za wcześnie się obijacie!', '', 0),
(15103, 'koKR', 'Pomocy! Proszę, pomóż mi!', '', 0),
(15106, 'koKR', 'Jak możesz mnie tu tak zostawić?', '', 0),
(15108, 'koKR', 'Czy ten ból kiedyś się skończy?', '', 0),
(15896, 'koKR', 'Intruzzzi przy więźniu! Zabić ich!!!', '', 0),
(17888, 'koKR', 'Praca musi trwać!', '', 0),
(17889, 'koKR', 'Sami się o to prosiliście!', '', 0),
(17890, 'koKR', 'Nie zmuszajcie mnie, żebym was zabił!', '', 0),
(17892, 'koKR', 'To musiało się stać...', '', 0),
(17893, 'koKR', 'Nie trzeba było tu przychodzić...', '', 0),
(17894, 'koKR', 'Ja... zasłużyłem na to...', '', 0),
(18707, 'koKR', 'Nareszcie wolność!', '', 0),
(18710, 'koKR', 'Jak możemy wam się kiedykolwiek odwdzięczyć?', '', 0),
(18711, 'koKR', 'Czekaliśmy na ten dzień całą wieczność!', '', 0),
(18712, 'koKR', 'Ból wreszcie minął.', '', 0),
(18713, 'koKR', 'Pluję na trupy tych plugawych nag.', '', 0),
(24893, 'koKR', 'Ahunie, twoja siła już nie wzrośnie!', 'Ahunie, twoja siła już nie wzrośnie!', 0),
(24894, 'koKR', 'Twoje lodowe rządy nigdy nie nastaną!', 'Twoje lodowe rządy nigdy nie nastaną!', 0),
(24895, 'koKR', 'Lodowy kamień stopniał!', 'Lodowy kamień stopniał!', 0),
(24930, 'koKR', 'Rozpoczyna się szturm Kręgu Ziemi.', 'Rozpoczyna się szturm Kręgu Ziemi.', 0),
(24931, 'koKR', 'Ahun się wycofuje. Jego obrona słabnie.', 'Ahun się wycofuje. Jego obrona słabnie.', 0),
(24932, 'koKR', 'Ahun wkrótce znów się wynurzy.', 'Ahun wkrótce znów się wynurzy.', 0),
(25373, 'koKR', 'Czy będziemy gotowi, gdy Ahun się wynurzy?', 'Czy będziemy gotowi, gdy Ahun się wynurzy?', 0),
(25374, 'koKR', 'Musisz przetrwać ataki sług Ahuna, podczas gdy my skupiamy nasze płomienie. Nie zbliżaj się do Władcy Mrozu, dopóki go nie osłabimy.', 'Musisz przetrwać ataki sług Ahuna, podczas gdy my skupiamy nasze płomienie. Nie zbliżaj się do Władcy Mrozu, dopóki go nie osłabimy.', 0),
(40437, 'koKR', 'Jak ŚMIESZ! Nie powstrzymasz nadejścia Lorda Ahuna!', '', 0),
(40442, 'koKR', 'Ten odłamek lodu niesie echo głębokiego, trzeszczącego dudnienia nacierających lodowców. Bijący od niego chłód kieruje twoje myśli ku martwej, niekończącej się zimie.', '', 0),
(40443, 'koKR', 'Narusz kamień i przyzwij Lorda Ahuna.', 'Narusz kamień i przyzwij Lorda Ahuna.', 0);
